css:
 .wrapper {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

 .wrapper iframe {
  aspect-ratio: 16/9;
  width: 100%;
  height: auto;
  margin: 0 auto !important;
  border: none;
}

 .vertical-slide-combo {
  width: 100%;
  margin: 0 auto;
  height: 100%;
  position: relative;
}

 .vertical-slide-combo .slide-area {
  height: 100%;
}

 .vertical-slide-combo .footer-area {
  background-color: transparent;
  width: 100%;
  max-width: 750px;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
  z-index: 100;
  box-sizing: border-box;
}

 .vertical-slide-combo .footer-area img {
  width: 100%;
}

 .vertical-slide-combo .btn-link {
  width: 100%;
  display: inline-block;
  text-align: center;
  text-decoration: none;
  font-size: min(4.33vw, 26px);
  font-weight: bold;
  background-color: #ffffff;
  color: #4682b4;
  padding: 0.6em 0.5em;
  border: 2px solid #4682b4;
  border-radius: 100vh;
  box-shadow: rgba(0, 0, 0, 0.15) 1.95px 1.95px 2.6px;
  box-sizing: border-box;
}

 .swiper-slide {
  display: grid;
  place-content: center;
  width: 100%;
  height: 100% !important;
  padding-bottom: min(40%, 200px);
  box-sizing: border-box;
  flex-shrink: 0;
  position: relative;
  transition-property: transform;
  overflow: hidden;
}

 .swiper-slide picture,
 .swiper-slide img,
 .swiper-slide video {
  display: inline-block;
  width: 100%;
  height: 100% !important;
  object-fit: var(--image-type);
}

 .swiper-slide .navigation-area * {
  margin-block: -0.175em;
}

 .swiper-slide .navigation-area {
  padding-top: .5em;
  display: grid;
  gap: .75em;
  text-align: center;
  background-color: #1b1c1e;
  color: #ffffff;
  font-size: 12px;
}

 .swiper-slide .navigation {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 1em;
}

 .swiper-slide .navigation a {
  color: #ffffff;
}

 .swiper-slide .copy-wright {
  margin-top: .25em;
  background-color: #000;
}

 .swiper {
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  width: 100%;
  height: 100%;
  padding: 0;
  z-index: 1;
}

 .swiper-pointer-events {
  touch-action: pan-y;
}

 .swiper-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  z-index: 1;
  display: flex;
  flex-direction: column;
  transform: translate3d(0px, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

 .swiper-scrollbar {
  border-radius: 10px;
  position: relative;
  -ms-touch-action: none;
  background: rgba(0, 0, 0, 0.1);
}

 .swiper-scrollbar-disabled>.swiper-scrollbar,
 .swiper-scrollbar.swiper-scrollbar-disabled {
  display: none !important;
}

 .swiper-horizontal>.swiper-scrollbar,
 .swiper-scrollbar.swiper-scrollbar-horizontal {
  position: absolute;
  left: 1%;
  bottom: 4px;
  top: auto;
  z-index: 50;
  height: 4px;
  width: 98%;
}

 .swiper-vertical>.swiper-scrollbar,
 .swiper-scrollbar.swiper-scrollbar-vertical {
  position: absolute;
  left: auto;
  right: 4px;
  top: 1%;
  z-index: 50;
  width: 4px;
  height: 98%;
}

 .swiper-scrollbar-drag {
  height: 100%;
  width: 100%;
  position: relative;
  background: rgba(0, 0, 0, 0.5);
  border-radius: 10px;
  left: 0;
  top: 0;
}

 .swiper-scrollbar-cursor-drag {
  cursor: move;
}

 .swiper-scrollbar-lock {
  display: none;
}

 * {
  box-sizing: border-box;
}

 .EDITABLE.vertical-slide-combo .swiper-slide img {
  max-width: 750px;
  margin-inline: auto;
}

 .EDITABLE.vertical-slide-combo .footer-area {
  opacity: 1;
}

 .EDITABLE.vertical-slide-combo .swiper-wrapper {
  overflow-y: scroll;
  scroll-snap-type: x mandatory;
}

 .EDITABLE.vertical-slide-combo .swiper-slide {
  overflow-y: scroll;
  scroll-snap-align: start;
}

p {
  margin: 0;
}

img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.infoLink__area,
.infoLink__area * {
  box-sizing: border-box;
}

.infoLink__area {
  width: 100%;
  height: auto;
  font-size: min(3vw, 16px);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  column-gap: 2.5%;
}

.infoLink--img__box {
  width: 15%;
  height: auto;
}

.infoLink--img__box img {
  aspect-ratio: 1/1;
  border-radius: 5px;
}

.infoLink--text__box {
  width: 65%;
  height: auto;
}

.infoLink--text__box .bold {
  font-weight: bold;
  font-size: 1.1em;
}

.infoLink--text__box .text {
  font-size: 0.8em;
  color: #999;
}

.infoLink--btn__box {
  width: 15%;
  height: auto;
  padding: 1em 0;
}

.infoLink--btn__box .link {
  text-decoration: none;
  color: #45A1CF;
  font-weight: bold;
  font-size: 0.9em;
  text-align: center;
  background-color: #efefef;
  padding: 0.2em 0.5em;
  display: block;
  border-radius: 10vw;
}

.infoLink--btn__box .text {
  color: #999;
  font-size: 0.75em;
  text-align: center;
}

img {
  width: 100%;
  height: auto;
  vertical-align: middle;
}

p {
  margin: 0;
}

.access__area,
.access__area * {
  box-sizing: border-box;
}

.access__area {
  width: 100%;
  height: auto;
  font-size: min(13vw, 16px);
  padding: 2em 0 1em;
  background-color: #d9f0f4;
}

.access__headBox {
  width: 100%;
  height: auto;
  padding: 1em 0;
  background-color: #f0fffe;
  position: relative;
}

.access__headBox .head {
  font-size: 2em;
  text-align: center;
  color: #89c1be;
  margin: 0.3em 0 0.5em;
}

.decorated-line {
  width: 70%;
  height: 8px;
  background: radial-gradient(circle, #89c1be 1px, transparent 1px) repeat-x;
  background-size: 6px 6px;
  position: relative;
  overflow: hidden;
  display: block;
  margin-left: auto;
  margin-right: auto;
}

.decorated-line::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
  height: 10px;
  background: radial-gradient(circle, #89c1be 2px, transparent 2px) repeat-x;
  background-size: 6px 6px;
  mask: radial-gradient(circle at center, black, transparent);
  -webkit-mask: radial-gradient(circle at center, black, transparent);
}

.access__mapBox {
  width: 75%;
  height: auto;
  margin: 1em auto 0;
}

@media screen and (max-width:600px) {
  .access__mapBox {
    width: 85%;
  }
}

.access__mapBox iframe {
  width: 100%;
  height: auto;
  aspect-ratio: 1/0.8;
}

.footer__area {
  width: 100%;
  height: auto;
  background-color: #69b0c4;
  color: #fff;
  text-align: center;
  padding: 1.5em 0;
}

.footer__area .companyName {
  font-size: 2em;
}

.footer__area .place {
  margin-top: 1em;
}

.footer__area .access {
  margin-top: 1em;
}

.widget-container {
  font-size: 16px;
  width: min(100%, 750px);
  margin-inline: auto;
  line-height: 1.35;
}

.map-link-image img {
  width: 100%;
  height: auto;
}

.map-link-item {
  display: grid;
  width: min(80%, 330px);
  margin: 0.5em auto;
  gap: 0.25em;
  opacity: 0;
  pointer-events: none;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.2s ease-in-out;
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
}

.map-link-item .item {
  display: grid;
  place-items: center;
  font-weight: 600;
  font-size: 1.2em;
  padding: 1.5em 1em;
  background-color: #666;
  color: #fff;
  cursor: pointer;
  transition: filter 0.2s ease-in-out;
}

.map-link-item .item:hover {
  filter: brightness(1.2);
}



.map-link-item .item[data-pref-id="1"] {
  aspect-ratio: 1/1;
  background-color: #23ac38 !important;
  margin-bottom: 1.5em;
}

.map-link-item .item[data-pref-id="21"] {
  aspect-ratio: 1/2;
}


.map-link-item .item[data-pref-id="36"],
.map-link-item .item[data-pref-id="37"],
.map-link-item .item[data-pref-id="38"],
.map-link-item .item[data-pref-id="39"] {
  background-color: #f1a2b7 !important;
}



.map-link-item .item[data-pref-id="37"],
.map-link-item .item[data-pref-id="38"] {
  margin-top: 1.5em;
}


.map-link-item .item[data-pref-id="47"] {
  margin-top: 1.5em;
}

.map-link-content {
  background-color: rgba(255, 255, 255, 0.85);
  padding: 1em;
  position: fixed;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  display: none;
}

.map-link-content.active {
  display: grid;
  place-content: center;
}

.map-link-close {
  position: fixed;
  top: 0;
  right: 0;
  padding: 1.5em;
  text-align: center;
  font-weight: 600;
  cursor: pointer;
  background-color: #000;
  color: #fff;
  text-align: center;
  border: none;
  outline: none;
  transition: filter 0.2s ease-in-out;
  line-height: 1;
}

.map-link-close:hover {
  filter: brightness(0.5);
}

.area-hover {
  filter: brightness(1.2);
}



