.map-link-popup {
  position: fixed;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  width: min(100%, 750px);
  padding: 1em;
  display: grid;
  place-items: center;
  z-index: 1000;
  gap: 1em;
  max-height: 90vh;
  overflow-y: auto;
  pointer-events: none;
}

.map-link-popup .title {
  width: fit-content;
  text-align: center;
  font-size: 1.25em;
  font-weight: 600;
  color: #fff;
  padding: 1em;
}

.map-link-popup .content {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, auto));
  gap: 1em;
  color: #fff;
  padding: 1.5em;
}

.map-link-popup .content .item {
  display: grid;
  place-items: center;
  font-weight: 600;
  transition: filter 0.2s ease-in-out;
}

.map-link-popup .content .item a {
  color: #fff !important;
}

.map-link-popup .content .item a:hover {
  filter: brightness(0.85);
}

.map-link-popup .content .item .name {
  font-size: 1.35em;
  font-weight: 600;
  line-height: 1.8;
}

.map-link-popup .content .item .text {
  font-size: 0.875em;
}

.map-link-popup-close {
  padding: 0.5em 1.5em;
  text-align: center;
  font-weight: 600;
  cursor: pointer;
  background-color: #000;
  color: #fff;
  opacity: 0;
}

.map-link-popup-close:hover {
  filter: brightness(0.85);
}

.map-link-popup-layer {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.75);
  z-index: 999;
  animation-delay: 0.5s;
}

.loading {
  position: fixed;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  font-size: 1em;
  background-color: #fff;
  padding: 1em;
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  z-index: 9000;
  animation: map-link-fadeOut 1s 2s ease-in-out forwards;
}

@media (max-width: 550px) {
  .map-link-content {
    position: fixed;
    top: 50%;
    translate: 0 -50%;
    max-height: 98vh;
    overflow-y: auto;
    padding: 5em 0;
  }
}

.no-item {
  pointer-events: none;
  filter: brightness(0.85);
}

.hidden {
  opacity: 0;
  pointer-events: none;
}

.fadeOut {
  animation: map-link-fadeOut 0.2s ease-in-out forwards;
}

.fadeIn {
  animation: map-link-fadeIn 0.2s ease-in-out forwards;
}

* {
  box-sizing: border-box;
}

a {
  text-decoration: none !important;
}

@keyframes map-link-fadeIn {
  from {
    opacity: 0;
    pointer-events: none;
    max-height: 0;
    overflow: hidden;
  }

  to {
    opacity: 1;
    pointer-events: auto;
    max-height: 100vh;
    overflow: visible;
  }
}

@keyframes map-link-fadeOut {
  from {
    opacity: 1;
    pointer-events: auto;
  }

  to {
    opacity: 0;
    pointer-events: none;
    z-index: -1;
  }
}



