.formAppearance__area .commentLeave__box .commentLeave__text {
  margin: 0;
  /* 内側の余白 */
  padding: 5px 20px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字色 */
  background: #efefef;
}

.formAppearance__area .requiredComment__text {
  margin-bottom: 20px;
}

.formAppearance__area .commentLeave__form label {
  /* 「コメント」「名前」「メール」「サイト」の文字の大きさ */
  font-size: 16px;
}



/*-- 名前、メール、サイトの入力部分 --*/
.formAppearance__area .commentLeave__form input[type="text"],
.formAppearance__area .commentLeave__form input[type="email"],
.formAppearance__area .commentLeave__form input[type="url"] {
  /* 入力部分の横幅 */
  width: 300px;
  max-width: calc(100% - 75px);
  /* 内側の余白 */
  padding: 5px 2px;
  /* 入力部分の枠線 */
  border: 1px solid #aaa;
  /* 入力部分の枠の角丸 */
  border-radius: 3px;
}



/*-- コメント --*/
.formAppearance__area .commentLeave__form .comment__form {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-orient: vertical;
  -webkit-box-direction: normal;
  -ms-flex-direction: column;
  flex-direction: column;
  /* コメント入力枠下の余白 */
  margin-bottom: 16px;
}

.formAppearance__area .commentLeave__form .comment__form textarea {
  max-width: 100%;
  height: 200px;
  border: 1px solid #aaa;
  border-radius: 3px;
}



/*-- 名前 --*/
.formAppearance__area .commentLeave__form .name__form {
  margin-bottom: 16px;
}

.formAppearance__area .commentLeave__form .name__form label {
  margin-right: 18px;
}



/*-- メール --*/
.formAppearance__area .commentLeave__form .mail__form {
  margin-bottom: 16px;
}

.formAppearance__area .commentLeave__form .mail__form label {
  margin-right: 3px;
}



/*-- サイト --*/
.formAppearance__area .commentLeave__form .site__form {
  margin-bottom: 16px;
}

.formAppearance__area .commentLeave__form .site__form label {
  margin-right: 14px;
}



/*-- 保存するか否かのチェックボックス --*/
.formAppearance__area .commentLeave__form .check__form {
  margin-bottom: 16px;
}



/*-- 「コメント送信」ボタン --*/
.formAppearance__area .commentLeave__form .commentSend__btn {
  max-width: 100%;
  height: auto;
  border: none;
  display: block;
  margin: 0 auto;
  /* 横幅 */
  width: 250px;
  /* ボタン内の余白 */
  padding: 10px 5px;
  /* ボタンの色 */
  background: #ff69b4;
  /* ボタンの文字色 */
  color: #fff;
}

 .google-drive-container {
   /*高さ
     動画サイズに合わせて、枠の点線と比較しながら下記の高さを揃えてください。
     動画の下に続くコンテンツが動画の後ろ側に回り込むのを防ぐためです。*/
   height:480px;
   position: relative;
   display: block;
   margin: 0 auto !important;
   background-image: url("/uploads/bfe454120d84a8f655922e0d517049998ede32e8dd77b3a9da1077e7ffde0224.png");
   background-repeat: no-repeat;
   background-size: 50px auto;
   background-position: 50% 49.5%;
   border: 1px dashed #000;
 }

 .google-drive-container iframe,
 .google-drive-container object,
 .google-drive-container embed {
   position: absolute;
   top: 0;
   left: 50%;
   transform: translatex(-50%);
   margin-top: 0 !important;
   margin-bottom: 0 !important;
 }

