 blockquote,
 iframe.instagram-media {
   /*真ん中寄せにしない場合は下記を削除*/
   margin: 0 auto !important;
 }

 .wrapper {
    position: relative;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
}

 .wrapper:before {
    content: "";
    display: block;
    padding-top: 56.25%;
    /* 高さと幅の比を16:9に固定。9/16*100=56.25 */
}

 .wrapper iframe {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}
